CREATE OR REPLACE FUNCTION public.handle_referral_reward()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  is_first_booking BOOLEAN;
  ref_row referrals%ROWTYPE;
BEGIN
  IF NEW.profile_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT COUNT(*) = 1 INTO is_first_booking
  FROM trial_bookings WHERE profile_id = NEW.profile_id;

  IF NOT is_first_booking THEN
    RETURN NEW;
  END IF;

  SELECT * INTO ref_row FROM referrals
  WHERE referred_id = NEW.profile_id AND status = 'pending'
  LIMIT 1;

  IF ref_row.id IS NOT NULL THEN
    UPDATE referrals SET status = 'rewarded' WHERE id = ref_row.id;
    UPDATE profiles SET referral_credit = referral_credit + 5 WHERE id = ref_row.referrer_id;
    UPDATE profiles SET referral_credit = referral_credit + 5 WHERE id = ref_row.referred_id;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_booking_profile_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  IF NEW.profile_id IS NULL THEN
    NEW.profile_id := auth.uid();
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_one_trial_per_partner()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.status NOT IN ('pending', 'confirmed', 'active', 'completed') THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.trial_bookings
    WHERE profile_id = NEW.profile_id
      AND partner_name = NEW.partner_name
      AND status IN ('pending', 'confirmed', 'active', 'completed')
      AND id != NEW.id
  ) THEN
    RAISE EXCEPTION 'ONE_TRIAL_PER_PARTNER: profile % already has a trial booking with %', NEW.profile_id, NEW.partner_name;
  END IF;

  RETURN NEW;
END;
$function$
